// ==============================================================
// WF3 - Validar e preparar (monday)
// Responsabilidade: finalizar ocorrencia manual do intermitente.
// Documentos externos nao participam deste calculo.
// ==============================================================

const COL_UUID = 'text_mm2xjend';
const COL_PROTOCOLO = 'text_mm2xsvg6';
const COL_DATA_INICIO = 'date_mm2xtp93';
const COL_DATA_FIM = 'date_mm2xrr5q';
const COL_EXPIRA_EM = 'date_mm2xrvt4';
const COL_CONCLUIDO_EM = 'date_mm2xh1vm';
const COL_EDITADO_EM = 'date_mm2x62fq';
const COL_STATUS = 'color_mm2xkqpc';
const COL_EDITADO = 'boolean_mm2x1aa4';
const COL_QTD_FALTAS = 'numeric_mm2xe2zk';
const COL_QTD_ATRASOS = 'numeric_mm2x18hh';
const COL_TOTAL_MIN = 'numeric_mm2x4fjj';
const COL_DIAS_EXTRAS = 'long_text_mm2x73w6';
const COL_DIAS_DESATIV = 'long_text_mm2xm820';
const COL_RESPOSTAS = 'long_text_mm2xtcpw';
const COL_TOTAL_MIN_DEVIDOS = 'numeric_mm3455ss';
const COL_DIAS_PERDE_VT = 'numeric_mm345xb6';
const COL_DIAS_PERDE_VR = 'numeric_mm34a3ph';
const COL_TRABALHA_SAB = 'color_mm34yyet';
const COL_QTD_SABADOS_EX = 'numeric_mm3bvgy';
const COL_SABADOS_EX_TXT = 'text_mm3bfn6h';
const COL_BENEF_LEDGER = 'long_text_mm3ct3hg';
const COL_STATUS_CANCELAMENTO = 'color_mm3b9v4n';
const COL_CONTRATO = 'text_mm2x1ktb';
const COL_CHAPA = 'text_mm33v9kp';
const COL_OPTANTE_VT = 'color_mm34ry47';
const COL_ITEM_ORIGEM = 'link_mm2x1rk0';

const webhook = $('Webhook1').first().json;
const payload = webhook.body && typeof webhook.body === 'object' ? webhook.body : {};
const uuid = webhook.query?.uuid || payload.uuid;
const respostas = Array.isArray(payload.respostas) ? payload.respostas : [];
const protocolo = payload.protocolo || null;
const diasExtras = Array.isArray(payload.dias_extras) ? payload.dias_extras : [];
const diasDesativ = Array.isArray(payload.dias_desativados) ? payload.dias_desativados : [];
const sabadosExtras = Array.isArray(payload.sabados_extras)
  ? payload.sabados_extras.filter(d => typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d))
  : [];
const ehCorrecaoFlag = !!payload.eh_correcao;

function parseSplitPayload(v) {
  if (!v || typeof v !== 'object') return null;
  const data = String(v.data_inicio_parte2 || '').trim();
  const c1 = String(v.contrato_parte1 || '').trim();
  const c2 = String(v.contrato_parte2 || '').trim();
  if (!data && !c1 && !c2) return null;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(data) || !c1 || !c2) {
    return { _erro: 'split_invalido', mensagem: 'Split invalido no payload de finalizacao.' };
  }
  return { data_inicio_parte2: data, contrato_parte1: c1, contrato_parte2: c2 };
}
const splitPayload = parseSplitPayload(payload.split);
if (splitPayload?._erro) return [{ json: { _statusCode: 400, _erro: splitPayload._erro, mensagem: splitPayload.mensagem } }];

function firstRealItem(items) {
  for (const it of items) {
    const j = it.json;
    if (j?.id && (j.column_values || j.name)) return j;
  }
  return null;
}
const item = firstRealItem($input.all());
if (!item) return [{ json: { _statusCode: 404, _erro: 'nao_encontrado', mensagem: 'Processamento nao encontrado.' } }];

const columnValues = item.column_values ?? [];
const getCol = id => columnValues.find(c => c.id === id);
const text = id => getCol(id)?.text ?? null;
const rawValue = id => getCol(id)?.value ?? null;

function parseCheckbox(id) {
  const v = rawValue(id);
  if (!v) return false;
  try { const p = typeof v === 'string' ? JSON.parse(v) : v; return p?.checked === true || p?.checked === 'true'; }
  catch { return false; }
}
function normLabel(v) { return String(v || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().trim(); }
function dateValue(d, withTime) {
  if (!d) return null;
  const x = d instanceof Date ? d : new Date(d);
  if (Number.isNaN(x.getTime())) return null;
  const yyyy = x.getUTCFullYear();
  const mm = String(x.getUTCMonth() + 1).padStart(2, '0');
  const dd = String(x.getUTCDate()).padStart(2, '0');
  if (!withTime) return { date: `${yyyy}-${mm}-${dd}` };
  const hh = String(x.getUTCHours()).padStart(2, '0');
  const mi = String(x.getUTCMinutes()).padStart(2, '0');
  const ss = String(x.getUTCSeconds()).padStart(2, '0');
  return { date: `${yyyy}-${mm}-${dd}`, time: `${hh}:${mi}:${ss}` };
}
// Feriados nacionais BR: fixos + Sexta-feira Santa (Pascoa - 2).
const __feriadosBrCache = new Map();
const __FERIADOS_BR_FIXOS = [
  { mm: 1, dd: 1 },
  { mm: 4, dd: 21 },
  { mm: 5, dd: 1 },
  { mm: 9, dd: 7 },
  { mm: 10, dd: 12 },
  { mm: 11, dd: 2 },
  { mm: 11, dd: 15 },
  { mm: 11, dd: 20 },
  { mm: 12, dd: 25 },
];
function __padFeriado(n) { return String(n).padStart(2, '0'); }
function __isoFeriado(y, m, d) { return `${y}-${__padFeriado(m)}-${__padFeriado(d)}`; }
function calcularPascoa(year) {
  const a = year % 19;
  const b = Math.floor(year / 100);
  const c = year % 100;
  const d = Math.floor(b / 4);
  const e = b % 4;
  const f = Math.floor((b + 8) / 25);
  const g = Math.floor((b - f + 1) / 3);
  const h = (19 * a + b - d - g + 15) % 30;
  const i = Math.floor(c / 4);
  const k = c % 4;
  const l = (32 + 2 * e + 2 * i - h - k) % 7;
  const m = Math.floor((a + 11 * h + 22 * l) / 451);
  const n = h + l - 7 * m + 114;
  return { mes: Math.floor(n / 31), dia: (n % 31) + 1 };
}
function feriadosDoAno(year) {
  if (__feriadosBrCache.has(year)) return __feriadosBrCache.get(year);
  const set = new Set();
  for (const f of __FERIADOS_BR_FIXOS) set.add(__isoFeriado(year, f.mm, f.dd));
  const p = calcularPascoa(year);
  const sextaSanta = new Date(Date.UTC(year, p.mes - 1, p.dia));
  sextaSanta.setUTCDate(sextaSanta.getUTCDate() - 2);
  set.add(sextaSanta.toISOString().slice(0, 10));
  __feriadosBrCache.set(year, set);
  return set;
}
function __feriadosBrNacional(iso) {
  if (!iso || String(iso).length < 10) return false;
  const year = Number(String(iso).slice(0, 4));
  if (!Number.isFinite(year)) return false;
  return feriadosDoAno(year).has(String(iso).slice(0, 10));
}

function dow(d) { return new Date(d + 'T00:00:00Z').getUTCDay(); }
function isSabado(d) { return dow(d) === 6; }
function isDomingo(d) { return dow(d) === 0; }
function jornadaMin(d) { if (isDomingo(d) || isFeriadoNacional(d)) return 0; if (isSabado(d)) return 240; return 480; }
function rangeDatas(inicio, fim) {
  const out = [];
  const cur = new Date(inicio + 'T00:00:00Z');
  const end = new Date(fim + 'T00:00:00Z');
  while (cur <= end) { out.push(cur.toISOString().slice(0, 10)); cur.setUTCDate(cur.getUTCDate() + 1); }
  return out;
}
function fail(code, mensagem, status = 400, extra = {}) {
  return [{ json: { _statusCode: status, _erro: code, mensagem, ...extra } }];
}

const statusNorm = normLabel(text(COL_STATUS));
const dataInicio = text(COL_DATA_INICIO);
const dataFim = text(COL_DATA_FIM);
const expiraEm = text(COL_EXPIRA_EM);
const concluidoEmAtual = text(COL_CONCLUIDO_EM);
const jaEstavaEditado = parseCheckbox(COL_EDITADO);
const agora = new Date();

if (statusNorm === 'EXPIRADO' || (expiraEm && agora > new Date(expiraEm + 'T23:59:59Z') && statusNorm !== 'CONCLUIDO')) {
  return fail('expirado', 'Link expirado.', 410);
}
const statusCancelamento = text(COL_STATUS_CANCELAMENTO);
const statusCancelamentoNorm = normLabel(statusCancelamento);
if (statusCancelamentoNorm === 'CANCELADA') {
  return fail('convocacao_cancelada', 'Esta convocacao foi cancelada.', 409, { status_cancelamento: statusCancelamento });
}
if (statusNorm === 'CONCLUIDO' && !ehCorrecaoFlag) {
  return fail('ja_concluido', 'Este formulario ja foi finalizado.', 409);
}
if (!protocolo || !/^PROT-[A-Z0-9-]+$/i.test(protocolo)) {
  return fail('protocolo_invalido', 'Protocolo ausente ou invalido.');
}

const sabadosExtrasAnteriores = String(text(COL_SABADOS_EX_TXT) || '')
  .split(/[,;\n]/)
  .map(s => s.trim())
  .filter(s => /^\d{4}-\d{2}-\d{2}$/.test(s));
const setAnteriores = new Set(sabadosExtrasAnteriores);
const setAtuais = new Set(sabadosExtras);
const sabadosRemovidos = sabadosExtrasAnteriores.filter(d => !setAtuais.has(d));
if (sabadosRemovidos.length > 0) {
  return fail('sabados_pagos_removidos', `Sabados extras ja pagos nao podem ser removidos: ${sabadosRemovidos.join(', ')}.`, 409, { sabados_removidos: sabadosRemovidos });
}
const sabadosExtrasNovos = sabadosExtras.filter(d => !setAnteriores.has(d));
const sabadosExtrasFinal = [...new Set([...sabadosExtrasAnteriores, ...sabadosExtras])].sort();
const sabadosExtrasSet = new Set(sabadosExtrasFinal);
const trabalhaSabado = normLabel(text(COL_TRABALHA_SAB)) === 'SIM';

function diaConta(d) {
  if (isDomingo(d) || isFeriadoNacional(d)) return false;
  if (isSabado(d)) return trabalhaSabado || sabadosExtrasSet.has(d);
  return true;
}

const diasBase = [];
if (dataInicio && dataFim) {
  for (const d of rangeDatas(dataInicio, dataFim)) {
    if (!isDomingo(d) && !isFeriadoNacional(d) && (!isSabado(d) || trabalhaSabado)) diasBase.push(d);
  }
}
const desativ = new Set(diasDesativ);
// Dias já cancelados (origem só-cancelamento no ledger): preservar, NÃO reprocessar como falta (não sobrepor).
const _ledgerCancel = parseLongTextJsonFromText(text(COL_BENEF_LEDGER), {});
const diasCancelados = new Set(Object.keys(_ledgerCancel || {}).filter(function(_d){ var _o = (_ledgerCancel[_d] && _ledgerCancel[_d].origens) || []; return Array.isArray(_o) && _o.length > 0 && _o.every(function(x){ return String(x).indexOf('cancelamento') === 0; }); }));
const diasValidos = [...new Set([...diasBase, ...diasExtras, ...sabadosExtrasFinal])].filter(d => !desativ.has(d) && !isFeriadoNacional(d) && !diasCancelados.has(d)).sort();
const mapaRespostas = new Map(respostas.map(r => [r.data, r]));
const respostasFinal = [];
for (const dia of diasValidos) {
  const r = mapaRespostas.get(dia);
  if (!r?.tipo) return fail('resposta_faltando', `Resposta faltando para o dia ${dia}.`);
  if (!['sem_ocorrencia', 'falta', 'atraso'].includes(r.tipo)) return fail('tipo_invalido', `Tipo invalido em ${dia}: ${r.tipo}`);
  if (r.tipo === 'atraso' && (!Number.isInteger(r.minutos_atraso) || r.minutos_atraso <= 0)) return fail('minutos_invalidos', `Minutos de atraso invalidos em ${dia}.`);
  respostasFinal.push({ data: dia, tipo: r.tipo, minutos_atraso: r.tipo === 'atraso' ? r.minutos_atraso : null });
}

const ledgerAntesRaw = parseLongTextJsonFromText(text(COL_BENEF_LEDGER), {});
const descontosPorDiaMap = new Map();

function parseLongTextJsonFromText(t, fallback) {
  if (!t) return fallback;
  try { return JSON.parse(t); } catch { return fallback; }
}
function normalizeLedgerEntry(data, raw) {
  const origens = Array.isArray(raw?.origens) ? raw.origens.map(String) : [];
  const vrPercent = Math.min(100, Number(raw?.vr_percentual || (raw?.vr ? 100 : 0)) || 0);
  const vtPercent = Math.min(100, Number(raw?.vt_percentual || (raw?.vt ? 100 : 0)) || 0);
  const e = {
    data,
    vr: vrPercent > 0,
    vt: vtPercent > 0,
    vr_tipo: raw?.vr_tipo || (vrPercent >= 100 ? 'integral' : (vrPercent > 0 ? 'parcial' : null)),
    vr_percentual: vrPercent,
    vt_percentual: vtPercent,
    minutos_atraso: Number(raw?.minutos_atraso || 0) || 0,
    origens,
  };
  if (!e.vr) e.vr_tipo = null;
  return e;
}
for (const [data, raw] of Object.entries(ledgerAntesRaw || {})) {
  if (/^\d{4}-\d{2}-\d{2}$/.test(data) && !isFeriadoNacional(data)) descontosPorDiaMap.set(data, normalizeLedgerEntry(data, raw || {}));
}
function descontoEntry(data) {
  if (!descontosPorDiaMap.has(data)) descontosPorDiaMap.set(data, { data, vr: false, vt: false, vr_tipo: null, vr_percentual: 0, vt_percentual: 0, minutos_atraso: 0, origens: [] });
  return descontosPorDiaMap.get(data);
}
function pushOrigem(e, origem) {
  if (origem && !e.origens.includes(origem)) e.origens.push(origem);
}
function addDesconto(data, opts) {
  if (!diaConta(data)) return;
  const e = descontoEntry(data);
  let tocou = false;
  if (opts.vt) {
    e.vt = true;
    e.vt_percentual = Math.min(100, Math.max(Number(e.vt_percentual || 0), 100));
    tocou = true;
  }
  if (opts.vr) {
    e.vr = true;
    if (opts.vr_tipo === 'atraso') {
      const jor = jornadaMin(data) || 480;
      const atrasoPct = Math.min(100, Math.round(((opts.minutos_atraso || 0) / jor) * 10000) / 100);
      if ((e.vr_percentual || 0) < 100) {
        e.vr_percentual = Math.min(100, Math.max(Number(e.vr_percentual || 0), atrasoPct));
        if (e.vr_percentual < 100) e.vr_tipo = 'atraso';
        e.minutos_atraso = Math.max(Number(e.minutos_atraso || 0), Number(opts.minutos_atraso || 0));
      }
    } else {
      const pct = opts.vr_percentual ?? 100;
      e.vr_percentual = Math.min(100, Number(e.vr_percentual || 0) + pct);
      e.vr_tipo = e.vr_percentual >= 100 ? 'integral' : 'parcial';
    }
    tocou = true;
  }
  if (tocou) pushOrigem(e, opts.origem);
}

for (const d of diasDesativ) addDesconto(d, { vt: true, vr: !isSabado(d), vr_tipo: 'integral', origem: 'desconsiderado' });
for (const r of respostasFinal) {
  if (r.tipo === 'falta') addDesconto(r.data, { vt: true, vr: !isSabado(r.data), vr_tipo: 'integral', origem: 'falta' });
  if (r.tipo === 'atraso' && !isSabado(r.data)) {
    const jorAtraso = jornadaMin(r.data) || 480;
    const trabalhado = jorAtraso - (r.minutos_atraso || 0);
    // Regra: so desconta VR (cheio) se trabalhou menos de 6h (360min). Senao apenas registra o atraso no Plan (qtd/minutos).
    if (trabalhado < 360) addDesconto(r.data, { vr: true, vr_tipo: 'integral', vr_percentual: 100, origem: 'atraso' });
  }
}

const descontosPorDia = [...descontosPorDiaMap.values()]
  .filter(d => d.vr || d.vt || (d.origens || []).length)
  .sort((a, b) => a.data.localeCompare(b.data));
const qtdFaltas = respostasFinal.filter(r => r.tipo === 'falta').length;
const qtdAtrasos = respostasFinal.filter(r => r.tipo === 'atraso').length;
const totalMin = respostasFinal.reduce((acc, r) => acc + (r.tipo === 'atraso' ? (r.minutos_atraso || 0) : 0), 0);
const diasPerdeVT = descontosPorDia.filter(d => d.vt_percentual > 0 || d.vt).length;
const diasPerdeVR = descontosPorDia.reduce((acc, d) => acc + ((d.vr_percentual || 0) / 100), 0);
let totalMinDevidos = 0;
const ledger = {};
for (const d of descontosPorDia) {
  const vrPct = Math.min(100, Number(d.vr_percentual || 0) || 0);
  const vtPct = Math.min(100, Number(d.vt_percentual || (d.vt ? 100 : 0)) || 0);
  if (vrPct > 0) {
    if (d.vr_tipo === 'atraso' && d.minutos_atraso) totalMinDevidos += d.minutos_atraso || 0;
    else totalMinDevidos += Math.round((jornadaMin(d.data) || 0) * (vrPct / 100));
  }
  if (vtPct > 0 || d.origens.includes('falta') || d.origens.includes('desconsiderado')) totalMinDevidos += Math.round((jornadaMin(d.data) || 0) * (vtPct / 100 || 1));
  ledger[d.data] = {
    vr: vrPct > 0,
    vt: vtPct > 0,
    vr_percentual: vrPct,
    vt_percentual: vtPct,
    origens: Array.from(new Set((d.origens || []).map(String)))
  };
  if (d.vr_tipo) ledger[d.data].vr_tipo = d.vr_tipo;
  if (d.minutos_atraso) ledger[d.data].minutos_atraso = d.minutos_atraso;
}

const ehReedicao = statusNorm === 'CONCLUIDO' || ehCorrecaoFlag;
const editadoFlag = ehReedicao || jaEstavaEditado;
const columnValuesUpdate = {
  [COL_STATUS]: { label: 'Concluído' },
  [COL_PROTOCOLO]: protocolo,
  [COL_CONCLUIDO_EM]: dateValue(concluidoEmAtual ? concluidoEmAtual : agora.toISOString(), true),
  [COL_EDITADO]: { checked: editadoFlag ? 'true' : 'false' },
  [COL_EDITADO_EM]: ehReedicao ? dateValue(agora.toISOString(), true) : null,
  [COL_QTD_FALTAS]: String(qtdFaltas),
  [COL_QTD_ATRASOS]: String(qtdAtrasos),
  [COL_TOTAL_MIN]: String(totalMin),
  [COL_TOTAL_MIN_DEVIDOS]: String(totalMinDevidos),
  [COL_DIAS_PERDE_VT]: String(diasPerdeVT),
  [COL_DIAS_PERDE_VR]: String(diasPerdeVR),
  [COL_DIAS_EXTRAS]: { text: JSON.stringify(diasExtras) },
  [COL_DIAS_DESATIV]: { text: JSON.stringify(diasDesativ) },
  [COL_RESPOSTAS]: { text: JSON.stringify(respostasFinal) },
  [COL_QTD_SABADOS_EX]: String(sabadosExtrasFinal.length),
  [COL_SABADOS_EX_TXT]: sabadosExtrasFinal.length ? sabadosExtrasFinal.join(', ') : '',
  [COL_BENEF_LEDGER]: { text: JSON.stringify(ledger) }
};
for (const k of Object.keys(columnValuesUpdate)) if (columnValuesUpdate[k] === null || columnValuesUpdate[k] === undefined) delete columnValuesUpdate[k];

function extrairOrigemUrl() {
  const link = getCol(COL_ITEM_ORIGEM);
  if (!link) return null;
  let url = null;
  if (link.value) { try { url = (typeof link.value === 'string' ? JSON.parse(link.value) : link.value)?.url || null; } catch {} }
  if (!url) url = link.text || null;
  return url || null;
}
function extrairItemOrigemId() {
  const m = String(extrairOrigemUrl() || '').match(/pulses\/(\d+)/);
  return m ? m[1] : null;
}
function extrairItemOrigemBoard() {
  const m = String(extrairOrigemUrl() || '').match(/boards\/(\d+)/);
  return m ? m[1] : null;
}

const nome = item.name;
const chapa = String(text(COL_CHAPA) || '').trim();
const contrato = text(COL_CONTRATO) || null;
function __normFer(v){return String(v||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toUpperCase().replace(/\s+/g,' ').trim();}
function isFeriadoNacional(iso){
  const c = __normFer(text(COL_CONTRATO));
  if (c.startsWith('SEDUC') || c === 'DETRAN') return false;
  const fer = (item && item._feriados) || [];
  if (fer.length) return fer.some(f => f.data===iso && (f.tipo==='NACIONAL' || (f.contratos||[]).indexOf(c)!==-1));
  return __feriadosBrNacional(iso);
}
const optanteVtTxt = text(COL_OPTANTE_VT) || 'NAO';
const itemOrigemId = extrairItemOrigemId();
const concluidoEmFinal = concluidoEmAtual || agora.toISOString().slice(0, 19).replace('T', ' ');

return [{ json: {
  _statusCode: 200,
  item_id: String(item.id),
  item_origem_id: itemOrigemId,
  item_origem_board: extrairItemOrigemBoard(),
  uuid,
  nome,
  chapa,
  contrato,
  optante_vt: optanteVtTxt,
  data_inicio: dataInicio,
  data_fim: dataFim,
  protocolo,
  column_values_json: JSON.stringify(columnValuesUpdate),
  respostas: respostasFinal,
  descontos_por_dia: descontosPorDia,
  qtd_faltas: qtdFaltas,
  qtd_atrasos: qtdAtrasos,
  total_min: totalMin,
  total_min_atraso: totalMin,
  total_min_devidos: totalMinDevidos,
  dias_perde_vt: diasPerdeVT,
  dias_perde_vr: diasPerdeVR,
  sabados_extras_final: sabadosExtrasFinal,
  sabados_extras_novos: sabadosExtrasNovos,
  qtd_sabados_extras: sabadosExtrasFinal.length,
  qtd_sabados_extras_novos: sabadosExtrasNovos.length,
  eh_correcao: ehCorrecaoFlag,
  eh_reedicao: ehReedicao,
  concluido_em: concluidoEmAtual || agora.toISOString(),
  concluido_em_final: concluidoEmFinal,
  split: splitPayload,
  editado: editadoFlag,
  editado_em: ehReedicao ? agora.toISOString() : null
} }];

const hist = $('Validar e preparar1').first().json;

const COL_STATUS = 'color_mm0r8mjr';
const COL_DATA_INICIO = 'date_mm0r6tyr';
const COL_DATA_FIM = 'date_mm0rzpyv';
const COL_RESIDUAL_VR = 'numeric_mm0r1691';
const COL_RESIDUAL_VT = 'numeric_mm0rtwwg';
const COL_DESCONTADO_VR = 'numeric_mm0rqy6z';
const COL_DESCONTADO_VT = 'numeric_mm0r6cn0';

function norm(v) {
  return String(v || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().trim();
}

function num(v) {
  return Number(String(v || '0').replace(',', '.')) || 0;
}

const descontos = [];

for (const item of $input.all()) {
  const j = item.json;
  if (!j || !j.id || !j.column_values) continue;

  const cols = {};
  for (const c of j.column_values) {
    cols[c.id] = {
      text: c.text,
      value: c.value
    };
  }

  const dataInicio = cols[COL_DATA_INICIO]?.text || null;
